setBubble(seat, 'HIT', 'dim');
while (true) {
  const v = evalHand(hands[seat]);
  if (v.total >= 17) break;
  await wait(250); await dealCardTo(seat); await wait(400);
}
const v = ...
if (v.bust) bubble BUST bad
else if (v.blackjack) bubble BLACKJACK good
else bubble STAND dim
```
