(() => {
  "use strict";

  const $ = (sel, el = document) => el.querySelector(sel);
  const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
  const fmt = (n) => "$" + Math.max(0, Math.round(n)).toLocaleString("en-US");

  const SUITS = [
    { key: "S", symbol: "♠", color: "black" },
    { key: "H", symbol: "♥", color: "red" },
    { key: "D", symbol: "♦", color: "red" },
    { key: "C", symbol: "♣", color: "black" },
  ];
  const RANKS = [
    { rank: "A", value: 11 },
    { rank: "2", value: 2 }, { rank: "3", value: 3 }, { rank: "4", value: 4 },
    { rank: "5", value: 5 }, { rank: "6", value: 6 }, { rank: "7", value: 7 },
    { rank: "8", value: 8 }, { rank: "9", value: 9 }, { rank: "10", value: 10 },
    { rank: "J", value: 10 }, { rank: "Q", value: 10 }, { rank: "K", value: 10 },
  ];
  const CHIP_VALUES = [1, 5, 25, 100, 500];
  const AI_SEATS = ["left", "right"];

  const el = {
    stage: $("#stage"),
    tableWrap: $("#tableWrap"),
    felt: $("#felt"),
    shoe: $("#shoe"),
    tray: $("#trayChips"),
    trayHint: $("#trayHint"),
    bankroll: $("#bankroll"),
    handNo: $("#handNo"),
    playerBank: $("#playerBank"),
    leftBank: $("#leftBank"),
    rightBank: $("#rightBank"),
    betValue: $("#betValue"),
    dealBtn: $("#dealBtn"),
    hitBtn: $("#hitBtn"),
    standBtn: $("#standBtn"),
    nextBtn: $("#nextBtn"),
    clearBtn: $("#clearBetBtn"),
    shopBtn: $("#shopBtn"),
