    banner: $("#banner"),
    bannerEyebrow: $("#bannerEyebrow"),
    bannerTitle: $("#bannerTitle"),
    bannerSub: $("#bannerSub"),
    toast: $("#toast"),
    live: $("#live"),
    playerBetStack: $("#playerBetStack"),
    leftBetStack: $("#leftBetStack"),
    rightBetStack: $("#rightBetStack"),
    hands: {
      player: $("#playerHand"),
      left: $("#leftHand"),
      right: $("#rightHand"),
      dealer: $("#dealerHand"),
    },
    totals: {
      player: $("#playerTotal"),
      left: $("#leftTotal"),
      right: $("#rightTotal"),
