103:   /* ---------------- sound ---------------- */
104:   let audio = null;
105:   function ctx() {
106:     if (!audio) {
107:       const AC = window.AudioContext || window.webkitAudioContext;
108:       if (AC) audio = new AC();
109:     }
110:     if (audio && audio.state === "suspended") audio.resume();
111:     return audio;
112:   }
113:   function tone(freq, dur = 0.07, type = "sine", gain = 0.035, delay = 0) {
114:     if (!state.sound) return;
115:     const ac = ctx();
116:     if (!ac) return;
117:     const t = ac.currentTime + delay;
118:     const osc = ac.createOscillator();
119:     const g = ac.createGain();
120:     osc.type = type;
121:     osc.frequency.setValueAtTime(freq, t);
122:     g.gain.setValueAtTime(0.0001, t);
123:     g.gain.exponentialRampToValueAtTime(gain, t + 0.008);
124:     g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
125:     osc.connect(g).connect(ac.destination);
126:     osc.start(t);
127:     osc.stop(t + dur + 0.02);
128:   }
129:   const sfx = {
130:     chip() { tone(1040, 0.045, "triangle", 0.03); tone(1480, 0.05, "triangle", 0.018, 0.03); },
131:     card() { tone(240, 0.055, "triangle", 0.022); tone(180, 0.05, "sine", 0.018, 0.02); },
132:     deal() { tone(300, 0.05, "sine", 0.02); },
133:     win() { [523, 659, 784, 1046].forEach((f, i) => tone(f, 0.22, "sine", 0.03, i * 0.075)); },
134:     blackjack() { [523, 659, 784, 1046, 1318].forEach((f, i) => tone(f, 0.3, "sine", 0.032, i * 0.08)); },
135:     lose() { tone(196, 0.22, "sine", 0.026); tone(147, 0.3, "sine", 0.022, 0.12); },
136:     push() { tone(392, 0.16, "sine", 0.022); tone(392, 0.16, "sine", 0.018, 0.14); },
137:     click() { tone(620, 0.04, "square", 0.012); },
