140:   /* ---------------- shoe & cards ---------------- */
141:   function buildShoe() {
142:     const cards = [];
143:     for (let d = 0; d < 6; d++) {
144:       for (const s of SUITS) for (const r of RANKS) cards.push({ ...r, suit: s.symbol, color: s.color });
145:     }
146:     for (let i = cards.length - 1; i > 0; i--) {
147:       const j = Math.floor(Math.random() * (i + 1));
148:       [cards[i], cards[j]] = [cards[j], cards[i]];
149:     }
150:     state.shoe = cards;
151:   }
152:   function drawCard() {
153:     if (state.shoe.length < 30) buildShoe();
154:     return state.shoe.pop();
155:   }
156:   function evalHand(cards) {
157:     let total = 0, aces = 0;
158:     for (const c of cards) {
159:       if (c.rank === "A") { total += 11; aces++; }
160:       else total += c.value;
161:     }
162:     while (total > 21 && aces > 0) { total -= 10; aces--; }
163:     return { total, soft: aces > 0, bust: total > 21, blackjack: cards.length === 2 && total === 21 };
164:   }
