170:       : `<span class="pip">${card.suit}</span>`;
171:     return `
172:       <div class="corner tl"><span class="rank">${card.rank}</span><span class="suit">${card.suit}</span></div>
173:       ${center}
174:       <div class="corner br"><span class="rank">${card.rank}</span><span class="suit">${card.suit}</span></div>`;
175:   }
