356:   function updateBankroll(immediate = false) {
357:     el.playerBank.textContent = fmt(state.bankroll);
358:     const start = bankDisplay;
359:     const end = state.bankroll;
360:     if (immediate || start === end) {
361:       bankDisplay = end;
362:       el.bankroll.textContent = fmt(end);
363:       return;
364:     }
365:     if (bankAnimation) cancelAnimationFrame(bankAnimation);
366:     const t0 = performance.now();
367:     const step = (now) => {
368:       const p = Math.min(1, (now - t0) / 480);
369:       const eased = 1 - Math.pow(1 - p, 3);
370:       bankDisplay = Math.round(start + (end - start) * eased);
371:       el.bankroll.textContent = fmt(bankDisplay);
372:       if (p < 1) bankAnimation = requestAnimationFrame(step);
373:     };
374:     bankAnimation = requestAnimationFrame(step);
375:   }
