479:   function chooseAIBet(ai) {
480:     if (ai.bank < 5) ai.bank += 500;
481:     const options = [5, 5, 10, 10, 25, 25, 50, 100];
482:     const affordable = options.filter((v) => v <= ai.bank);
483:     return affordable[Math.floor(Math.random() * affordable.length)] || 0;
