486:   async function startRound() {
487:     if (state.phase !== "bet" || state.busy) return;
488:     if (state.bet <= 0 || state.bet > state.bankroll) return;
489:     state.busy = true;
490:     state.phase = "dealing";
491:     state.round++;
492:     el.handNo.textContent = "#" + String(state.round).padStart(2, "0");
493:     hideBanner();
494:     resetTableForRound();
495:     renderPlayerBet();
496:     setHint("Dealing…");
497:     ctx();
498: 
499:     state.bankroll -= state.bet;
500:     updateBankroll();
501: 
502:     for (const seat of AI_SEATS) {
503:       const bet = chooseAIBet(state.ai[seat]);
504:       state.ai[seat].bet = bet;
505:       state.ai[seat].bank -= bet;
506:     }
507:     updateAI();
508:     renderAIBets();
509: 
510:     buildShoeIfNeeded();
511:     updateControls();
512:     announce("Cards are being dealt.");
513: 
514:     for (let pass = 0; pass < 2; pass++) {
515:       for (const seat of ["player", "left", "right", "dealer"]) {
516:         const hidden = pass === 1 && seat === "dealer";
517:         await dealCardTo(seat, hidden);
518:         await wait(190);
519:       }
520:     }
521: 
522:     state.busy = false;
523:     state.phase = "player";
524:     updateControls();
525:     setActive("player");
526:     renderPlayerBet();
527: 
528:     if (evalHand(state.hands.player).blackjack) {
529:       setBubble("player", "Blackjack!", "good");
530:       announce("Blackjack! You have 21.");
531:       setHint("");
532:       await wait(800);
533:       await endPlayerTurn();
534:     } else {
535:       setHint("");
536:       announce(`Your hand is ${evalHand(state.hands.player).total}. Hit or stand.`);
537:       sfx.deal();
538:     }
539:   }
