545:   async function playerHit() {
546:     if (state.phase !== "player" || state.busy) return;
547:     state.busy = true;
548:     updateControls();
549:     setHint("");
550:     await dealCardTo("player");
551:     const hand = evalHand(state.hands.player);
552:     announce(`You drew. Total ${hand.total}.`);
553:     if (hand.bust) {
554:       setBubble("player", "Bust", "bad");
555:       sfx.lose();
556:       await wait(650);
557:       await endPlayerTurn();
558:       return;
559:     }
560:     if (hand.total === 21) {
561:       setBubble("player", "21", "good");
562:       await wait(500);
563:       await endPlayerTurn();
564:       return;
565:     }
566:     state.busy = false;
567:     updateControls();
568:     setHint("");
569:   }
