580:   async function endPlayerTurn() {
581:     state.busy = true;
582:     setActive(null);
583:     state.phase = "ai";
584:     updateControls();
585:     setHint("");
586: 
587:     for (const seat of AI_SEATS) {
588:       await playAI(seat);
