597:   async function playAI(seat) {
598:     const ai = state.ai[seat];
599:     setActive(seat);
600:     setBubble(seat, "Thinking", "dim");
601:     await wait(420);
602:     let hand = evalHand(state.hands[seat]);
603:     if (hand.blackjack) {
604:       setBubble(seat, "Blackjack!", "good");
605:       await wait(550);
606:       setActive(null);
607:       return;
608:     }
609:     while (hand.total < 17) {
610:       setBubble(seat, "Hit", "dim");
611:       await wait(300);
612:       await dealCardTo(seat);
613:       await wait(440);
614:       hand = evalHand(state.hands[seat]);
615:     }
616:     if (hand.bust) {
617:       setBubble(seat, "Bust", "bad");
618:       sfx.lose();
619:     } else {
620:       setBubble(seat, "Stand", "dim");
621:     }
622:     await wait(480);
623:     setActive(null);
624:   }
