627:     setActive("dealer");
628:     setHint("");
629:     await wait(300);
630:     if (state.dealerHidden) {
631:       setBubble("dealer", "Revealing…", "dim");
632:       await revealHole();
633:       await wait(420);
634:     }
635:     const allBusted = ["player", ...AI_SEATS].every((seat) => evalHand(state.hands[seat]).bust);
636:     let hand = evalHand(state.hands.dealer);
637:     if (allBusted) {
638:       setBubble("dealer", "Takes the bets", "dim");
639:       await wait(650);
640:       setActive(null);
641:       return;
642:     }
643:     while (hand.total < 17) {
644:       setBubble("dealer", "Hit", "dim");
645:       await wait(320);
646:       await dealCardTo("dealer");
647:       await wait(500);
648:       hand = evalHand(state.hands.dealer);
