666:     const anim = hiddenEl.animate(
667:       [{ transform: "rotateY(0deg)" }, { transform: "rotateY(90deg)" }],
668:       { duration: 160, easing: "ease-in", fill: "forwards" }
669:     );
670:     await anim.finished.catch(() => {});
671:     const faceEl = makeCardEl(realCard);
672:     faceEl.style.transform = "rotateY(-90deg)";
673:     hiddenEl.replaceWith(faceEl);
