684:   function settleHand(seat, dealerHand) {
685:     const hand = evalHand(state.hands[seat]);
686:     const bet = seat === "player" ? state.bet : state.ai[seat].bet;
687:     if (hand.bust) return { key: "lose", net: -bet, payout: 0, label: "Bust" };
688:     if (hand.blackjack && !dealerHand.blackjack) {
689:       return { key: "blackjack", net: bet * 1.5, payout: bet * 2.5, label: "Blackjack" };
690:     }
691:     if (hand.blackjack && dealerHand.blackjack) return { key: "push", net: 0, payout: bet, label: "Push" };
692:     if (dealerHand.blackjack) return { key: "lose", net: -bet, payout: 0, label: "Lose" };
693:     if (dealerHand.bust) return { key: "win", net: bet, payout: bet * 2, label: "Win" };
694:     if (hand.total > dealerHand.total) return { key: "win", net: bet, payout: bet * 2, label: "Win" };
695:     if (hand.total === dealerHand.total) return { key: "push", net: 0, payout: bet, label: "Push" };
696:     return { key: "lose", net: -bet, payout: 0, label: "Lose" };
