723:       const tone = res.key === "win" || res.key === "blackjack" ? "good" : res.key === "push" ? "dim" : "bad";
724:       const label = res.key === "win" ? `Win +${fmt(res.net)}` : res.key === "blackjack" ? `21 +${fmt(res.net)}` : res.key === "push" ? "Push" : seat === "left" || seat === "right" ? (res.label === "Bust" ? "Bust" : `−${fmt(-res.net)}`) : res.label;
725:       setBubble(seat, label, tone, true);
726:     }
727: 
728:     const p = results.player;
729:     const playerTone = p.key === "win" || p.key === "blackjack" ? "good" : p.key === "push" ? "dim" : "bad";
730:     setBubble("player", p.key === "blackjack" ? "Blackjack!" : p.key === "win" ? `Win +${fmt(p.net)}` : p.key === "push" ? "Push" : p.label === "Bust" ? "Bust" : `−${fmt(-p.net)}`, playerTone, true);
731:     const betLabel = document.getElementById("betLabel");
732:     betLabel.textContent = "Result";
733:     document.getElementById("betPanel").className = "bet-panel result " + (p.key === "win" || p.key === "blackjack" ? "is-win" : p.key === "push" ? "is-push" : "is-lose");
734:     updateAllTotals();
735:     updateControls();
736:     el.betValue.textContent = p.net > 0 ? "+" + fmt(p.net) : p.net < 0 ? "−" + fmt(-p.net) : "Push";
737:     state.busy = false;
738:     el.nextBtn.disabled = false;
739:     setHint("");
740:     announce(`Dealer has ${dealerHand.total}. ` + (p.key === "blackjack" ? `Blackjack! You win ${fmt(p.net)}.` : p.key === "win" ? `You win ${fmt(p.net)}.` : p.key === "push" ? "Push." : `You lose ${fmt(state.bet)}.`));
741: 
742:     if (p.key === "blackjack") {
743:       showBanner({ eyebrow: "Natural 21 • pays 3 to 2", title: "Blackjack", sub: `+${fmt(p.net)}`, tone: "win" });
744:       sfx.blackjack();
745:     } else if (p.key === "win") {
746:       showBanner({ eyebrow: "Hand complete", title: "You win", sub: `+${fmt(p.net)}`, tone: "win" });
747:       sfx.win();
748:     } else if (p.key === "push") {
749:       showBanner({ eyebrow: "Hand complete", title: "Push", sub: "Bet returned" });
750:       sfx.push();
751:     } else if (p.label === "Bust") {
752:       showBanner({ eyebrow: `Dealer ${dealerHand.total}`, title: "Bust", sub: `−${fmt(state.bet)}`, tone: "lose" });
753:       sfx.lose();
754:     } else {
755:       showBanner({ eyebrow: `Dealer ${dealerHand.total} • You ${evalHand(state.hands.player).total}`, title: "Dealer wins", sub: `−${fmt(state.bet)}`, tone: "lose" });
756:       sfx.lose();
