import { createRequire } from 'node:module';
const runtime = '/home/runner/.local/share/omgithub-playwright';
const require = createRequire(runtime + '/package.json');
const { chromium } = require('playwright');

const url = 'http://localhost:3002/';
const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] });
const errors = [];
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
await page.goto(url, { waitUntil: 'load' });
await page.waitForTimeout(700);

const snap = async (label) => {
  const data = await page.evaluate(() => {
    const t = (id) => document.querySelector(id)?.textContent?.trim() ?? null;
    const vis = (id) => {
      const n = document.querySelector(id);
      if (!n) return 'missing';
      const s = getComputedStyle(n);
      return n.hidden || s.display === 'none' || s.visibility === 'hidden' ? 'hidden' : 'visible';
    };
    return {
      bankroll: t('#bankroll'),
      handNo: t('#handNo'),
      bet: t('#betValue'),
      betLabel: t('#betLabel'),
      deal: vis('#dealBtn'),
      hit: vis('#hitBtn'),
      stand: vis('#standBtn'),
      next: vis('#nextBtn'),
      cards: {
        player: document.querySelectorAll('#playerHand .card').length,
        left: document.querySelectorAll('#leftHand .card').length,
        right: document.querySelectorAll('#rightHand .card').length,
        dealer: document.querySelectorAll('#dealerHand .card').length,
      },
      totals: {
        player: t('#playerTotal'), dealer: t('#dealerTotal'),
        left: t('#leftTotal'), right: t('#rightTotal'),
      },
      bubbles: {
        player: t('#playerBubble'), dealer: t('#dealerBubble'),
        left: t('#leftBubble'), right: t('#rightBubble'),
      },
      banner: t('#bannerTitle'),
      live: t('#live'),
    };
  });
  console.log(label, JSON.stringify(data));
  return data;
};

const click = async (sel) => { await page.click(sel); await page.waitForTimeout(120); };

await snap('initial');

// ---- Round 1: place 125, deal, stand ----
await page.click('.tray-slot[data-value="25"]');
await page.click('.tray-slot[data-value="100"]');
await page.waitForTimeout(200);
const betState = await snap('after-bet');
if (betState.bet !== '$125') throw new Error('Bet total wrong: ' + betState.bet);

await click('#dealBtn');
await page.waitForSelector('#hitBtn:visible', { timeout: 8000 });
const dealt = await snap('after-deal');
if (dealt.cards.player !== 2 || dealt.cards.dealer !== 2) throw new Error('Wrong card counts after deal');
if (dealt.handNo !== '#01') throw new Error('Hand number wrong: ' + dealt.handNo);

// hit if hand is below 21 (always allowed; may bust, that's fine)
await click('#hitBtn');
await page.waitForTimeout(900);
const afterHit = await snap('after-hit');
if (afterHit.cards.player < 3) throw new Error('Hit did not draw a card');

const playerTotal = parseInt(afterHit.totals.player, 10);
if (!afterHit.bubbles.player?.includes('Bust')) {
  await click('#standBtn');
} 
await page.waitForSelector('#nextBtn:visible', { timeout: 15000 });
const resolved = await snap('resolved');
if (!resolved.banner) throw new Error('No result banner');
console.log('RESULT:', resolved.betLabel, resolved.bet, '| banner:', resolved.banner);

await click('#nextBtn');
await page.waitForTimeout(500);
const next = await snap('next-round');
if (next.bet !== '$0' || next.handNo !== '#02') throw new Error('Next round did not reset properly');

// ---- Round 2: 5 chip, deal, stand ----
await page.click('.tray-slot[data-value="5"]');
await page.waitForTimeout(100);
await click('#dealBtn');
await page.waitForSelector('#hitBtn:visible', { timeout: 8000 });
await click('#standBtn');
await page.waitForSelector('#nextBtn:visible', { timeout: 15000 });
await snap('round2-resolved');
await click('#nextBtn');
await page.waitForTimeout(400);

// ---- Shop modal ----
await click('#shopBtn');
const shopOpen = await page.evaluate(() => document.querySelector('#shopModal').classList.contains('open'));
if (!shopOpen) throw new Error('Shop did not open');
await page.keyboard.press('Escape');
await page.waitForTimeout(300);
const shopClosed = await page.evaluate(() => !document.querySelector('#shopModal').classList.contains('open'));
if (!shopClosed) throw new Error('Shop did not close');

// ---- Enter key to deal ----
await page.click('.tray-slot[data-value="1"]');
await page.keyboard.press('Enter');
await page.waitForSelector('#hitBtn:visible', { timeout: 8000 });
await snap('enter-key-deal');
console.log('Enter-key deal: OK');

// ---- Mobile layout check ----
const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
mobile.on('pageerror', (e) => errors.push('mobile pageerror: ' + e.message));
await mobile.goto(url, { waitUntil: 'load' });
await mobile.waitForTimeout(800);
const layout = await mobile.evaluate(() => {
  const wrap = document.querySelector('#tableWrap').getBoundingClientRect();
  const actions = document.querySelector('#actions').getBoundingClientRect();
  const shop = document.querySelector('#shopBtn').getBoundingClientRect();
  return {
    viewport: [innerWidth, innerHeight],
    wrap: [Math.round(wrap.x), Math.round(wrap.y), Math.round(wrap.width), Math.round(wrap.height)],
    wrapFitsX: wrap.x >= 0 && wrap.right <= innerWidth,
    actionsVisible: actions.top < innerHeight && actions.bottom > 0,
    shopVisible: shop.top < innerHeight && shop.bottom > 0,
    overflowX: document.documentElement.scrollWidth > innerWidth,
  };
});
console.log('mobile layout', JSON.stringify(layout));
await mobile.screenshot({ path: '/tmp/opencode/mobile-check.jpg', type: 'jpeg', quality: 70 });

console.log('ERRORS:', errors.length ? errors : 'none');
await page.screenshot({ path: '/tmp/opencode/desktop-check.jpg', type: 'jpeg', quality: 70 });
await browser.close();
if (errors.length) process.exitCode = 1;

