const rects = await page.evaluate(() => {
  const r = (sel) => { const b = document.querySelector(sel)?.getBoundingClientRect(); return b ? [Math.round(b.x), Math.round(b.y), Math.round(b.width), Math.round(b.height)] : null; };
  return {
    felt: r('#felt'), tray: r('#chipTray'), bet: r('#playerBetStack'),
    hand: r('#playerHand'), panel: r('#betPanel'), actions: r('#actions'),
    betText: document.querySelector('#betValue').textContent,
