const inside = (r) => r && r[0] >= fx - 1 && r[1] >= fy - 1 && r[0] + r[2] <= fx + fw + 1 && r[1] + r[3] <= fy + fh + 1;
console.log('player bet stack inside felt:', inside(rects.bet));
const overlap = (a, b) => a && b && a[0] < b[0] + b[2] && b[0] < a[0] + a[2] && a[1] < b[1] + b[3] && b[1] < a[1] + a[3];
console.log('tray overlaps player bet stack:', overlap(rects.tray, rects.bet));
console.log('tray overlaps player hand:', overlap(rects.tray, rects.hand));

await page.screenshot({ path: '/tmp/opencode/bet-layout.png' });

await page.click('#dealBtn');
await page.waitForSelector('#hitBtn:visible', { timeout: 8000 });
await page.waitForTimeout(500);
await page.screenshot({ path: '/tmp/opencode/player-turn.png' });

// stand through
await page.click('#standBtn');
await page.waitForSelector('#nextBtn:visible', { timeout: 20000 });
