}));
console.log('resolved state', JSON.stringify(resolvedState));

await page.click('#nextBtn');
await page.waitForTimeout(500);
const resetState = await page.evaluate(() => ({
  bannerHidden: document.querySelector('#banner').hidden,
  panelClass: document.querySelector('#betPanel').className,
  betLabel: document.querySelector('#betLabel').textContent,
  betValue: document.querySelector('#betValue').textContent,
