  trayEnabled: [...document.querySelectorAll('.tray-slot')].map((b) => !b.disabled),
}));
console.log('reset state', JSON.stringify(resetState));
await page.screenshot({ path: '/tmp/opencode/reset.png' });

// shop screenshot
await page.click('#shopBtn');
await page.waitForTimeout(500);
await page.screenshot({ path: '/tmp/opencode/shop.png' });

console.log('ERRORS:', errors.length ? errors : 'none');
await browser.close();

