import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');

const url = 'http://localhost:3002/';
const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] });
const errors = [];
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
await page.goto(url, { waitUntil: 'load' });
await page.waitForTimeout(700);

const money = (s) => Number(String(s).replace(/[^0-9.-]/g, ''));
const state = () => page.evaluate(() => ({
  bank: document.querySelector('#bankroll').textContent,
  bet: document.querySelector('#betValue').textContent,
  label: document.querySelector('#betLabel').textContent,
  hitVisible: !document.querySelector('#hitBtn').hidden,
  hitDisabled: document.querySelector('#hitBtn').disabled,
  nextVisible: !document.querySelector('#nextBtn').hidden,
  banner: document.querySelector('#banner').hidden ? '' : document.querySelector('#bannerTitle').textContent,
  playerCards: document.querySelectorAll('#playerHand .card').length,
  dealerCards: document.querySelectorAll('#dealerHand .card').length,
  dealerBacks: document.querySelectorAll('#dealerHand .card--back').length,
  playerTotal: document.querySelector('#playerTotal').textContent,
  handNo: document.querySelector('#handNo').textContent,
}));

let rounds = 0, blackjacks = 0, busts = 0, pushes = 0, wins = 0, losses = 0;
for (let i = 0; i < 15; i++) {
  const before = await state();
  const bankBefore = money(before.bank);
  const chip = [1, 5, 25][i % 3];
  await page.click(`.tray-slot[data-value="${chip}"]`);
  await page.waitForTimeout(60);
  const bet = money((await state()).bet);
  if (bet !== chip) throw new Error(`Round ${i}: bet ${bet} != ${chip}`);

  await page.click('#dealBtn');
  await page.waitForFunction(() => !document.querySelector('#hitBtn').hidden, null, { timeout: 12000 });

  // Sometimes hit, but stop the loop when disabled via blackjack.
  const hits = i % 4 === 0 ? 0 : 1 + (i % 7 === 0 ? 1 : 0);
  for (let h = 0; h < hits; h++) {
    const s = await state();
    if (s.hitDisabled || !s.hitVisible) break;
    const total = money(s.playerTotal);
    if (total >= 17) break;
    await page.click('#hitBtn');
    await page.waitForTimeout(450);
  }

  // Attempt a hit during the blackjack celebration window (should be a no-op).
  const preStand = await state();
  if (preStand.hitDisabled && preStand.hitVisible) {
    const cardsBefore = preStand.playerCards;
    await page.click('#hitBtn', { force: true }).catch(() => {});
    await page.waitForTimeout(120);
    const cardsAfter = (await state()).playerCards;
    if (cardsAfter !== cardsBefore) throw new Error('Hit during blackjack pause changed the hand');
    blackjacks++;
  }

  if (!(await state()).nextVisible) {
    const s = await state();
    if (s.hitVisible && !s.hitDisabled) {
      await page.click('#standBtn');
    }
  }

  await page.waitForSelector('#nextBtn:visible', { timeout: 25000 });
  await page.waitForTimeout(350);
  const after = await state();
  const bankAfter = money(after.bank);
  const result = after.bet; // "+$x", "−$x", "Push"
  const net = result === 'Push' ? 0 : money(result);
  const delta = bankAfter - bankBefore;
  if (net !== delta) {
    throw new Error(`Round ${i + 1} bankroll mismatch: before ${bankBefore}, after ${bankAfter}, result ${result}, delta ${delta}, net ${net}`);
  }
  if (after.playerCards < 2 || after.dealerCards < 2) throw new Error(`Round ${i + 1}: missing cards`);
  if (after.dealerBacks !== 0) throw new Error(`Round ${i + 1}: hole card never revealed`);
  const b = after.banner;
  if (/Blackjack/.test(b)) blackjacks++;
  else if (/Bust/.test(b)) busts++;
  else if (/Push/.test(b)) pushes++;
  else if (/win/i.test(b)) wins++;
  else if (/Dealer wins/.test(b)) losses++;
  console.log(`round ${i + 1}: ${before.handNo} bet $${bet} -> ${result} | bank $${bankBefore} -> $${bankAfter} | ${b}`);
  rounds++;

  await page.click('#nextBtn');
  await page.waitForTimeout(350);
  const reset = await state();
  if (money(reset.bet) !== 0) throw new Error(`Round ${i + 1}: bet not cleared on reset`);
  if (reset.banner) throw new Error(`Round ${i + 1}: banner still visible after next round`);
}

console.log(`SUMMARY rounds=${rounds} blackjacks=${blackjacks} busts=${busts} pushes=${pushes} wins=${wins} losses=${losses}`);

// ---- Mobile touch round ----
const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
mobile.on('pageerror', (e) => errors.push('mobile pageerror: ' + e.message));
await mobile.goto(url, { waitUntil: 'load' });
await mobile.waitForTimeout(700);
await mobile.tap('.tray-slot[data-value="25"]');
await mobile.tap('.tray-slot[data-value="5"]');
await mobile.waitForTimeout(150);
await mobile.tap('#dealBtn');
await mobile.waitForFunction(() => !document.querySelector('#hitBtn').hidden, null, { timeout: 12000 });
const mobileTurn = await mobile.evaluate(() => ({
  bet: document.querySelector('#betValue').textContent,
  cards: document.querySelectorAll('#playerHand .card').length,
  playerTotal: document.querySelector('#playerTotal').textContent,
  hitDisabled: document.querySelector('#hitBtn').disabled,
  standVisible: !document.querySelector('#standBtn').hidden,
  overflowX: document.documentElement.scrollWidth > innerWidth,
}));
console.log('mobile turn', JSON.stringify(mobileTurn));
if (!mobileTurn.standVisible || mobileTurn.hitDisabled || mobileTurn.cards !== 2) throw new Error('Mobile controls broken');
await mobile.tap('#hitBtn');
await mobile.waitForTimeout(900);
const mobileAfterHit = await mobile.evaluate(() => ({
  cards: document.querySelectorAll('#playerHand .card').length,
  total: document.querySelector('#playerTotal').textContent,
  hitVisible: !document.querySelector('#hitBtn').hidden,
  standVisible: !document.querySelector('#standBtn').hidden,
}));
console.log('mobile after hit', JSON.stringify(mobileAfterHit));
if (mobileAfterHit.cards !== 3) throw new Error('Mobile hit failed');
if (mobileAfterHit.standVisible) {
  await mobile.tap('#standBtn');
}
await mobile.waitForSelector('#nextBtn:visible', { timeout: 25000 });
console.log('mobile settled', JSON.stringify(await mobile.evaluate(() => ({
  banner: document.querySelector('#bannerTitle').textContent,
  next: !document.querySelector('#nextBtn').hidden,
  bank: document.querySelector('#bankroll').textContent,
}))));
await mobile.screenshot({ path: '/tmp/opencode/mobile-final.jpg', type: 'jpeg', quality: 70 });

console.log('ERRORS:', errors.length ? errors : 'none');
await browser.close();
if (errors.length) process.exitCode = 1;

